<?php require_once 'header.php'; function createSlug($str){$u=['a'=>'á|à|ả|ã|ạ|ă|ắ|ặ|ằ|ẳ|ẵ|â|ấ|ầ|ẩ|ẫ|ậ','d'=>'đ','e'=>'é|è|ẻ|ẽ|ẹ|ê|ế|ề|ể|ễ|ệ','i'=>'í|ì|ỉ|ĩ|ị','o'=>'ó|ò|ỏ|õ|ọ|ô|ố|ồ|ổ|ỗ|ộ|ơ|ớ|ờ|ở|ỡ|ợ','u'=>'ú|ù|ủ|ũ|ụ|ư|ứ|ừ|ử|ữ|ự','y'=>'ý|ỳ|ỷ|ỹ|ỵ'];foreach($u as $n=>$v)$str=preg_replace("/($v)/i",$n,$str);$str=strtolower($str);$str=preg_replace('/[^a-z0-9\-]/','-',$str);return trim(preg_replace('/-+/','-',$str),'-');} $id=max(1,(int)($_GET['id']??0));$st=$conn->prepare("SELECT * FROM news WHERE id=?");$st->bind_param('i',$id);$st->execute();$n=$st->get_result()->fetch_assoc();$st->close();if(!$n){header('Location: '.$base_url.'tin-tuc');exit;}$related=$conn->query("SELECT * FROM news WHERE id<>".(int)$id." ORDER BY created_at DESC LIMIT 4"); ?>
