adius:7px;background:#fff;color:var(--primary-dark);font-weight:bold;cursor:pointer}@media(max-width:850px){.article-shell{grid-template-columns:1fr}.article-side{position:static}.article-header h1{font-size:27px}}@media(max-width:520px){.article-cover{height:230px}.article-header,.article-content{padding-left:15px;padding-right:15px}}
